/*Table structure for table `gov_approval_decisions` */

DROP TABLE IF EXISTS `gov_approval_decisions`;

CREATE TABLE `gov_approval_decisions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `approval_decision_id` varchar(100) NOT NULL,
  `approval_request_id` varchar(100) NOT NULL,
  `approver_id` varchar(255) NOT NULL,
  `approver_role` varchar(100) NOT NULL,
  `decision` enum('APPROVE','DENY') NOT NULL,
  `reason` text NOT NULL,
  `decision_hash` char(64) NOT NULL,
  `decided_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gov_approval_decision_id` (`approval_decision_id`),
  KEY `idx_gov_approval_decision_request` (`approval_request_id`,`decided_at`),
  CONSTRAINT `fk_gov_approval_decision_request` FOREIGN KEY (`approval_request_id`) REFERENCES `gov_approval_requests` (`approval_request_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `gov_approval_decisions` */

/*Table structure for table `gov_approval_requests` */

DROP TABLE IF EXISTS `gov_approval_requests`;

CREATE TABLE `gov_approval_requests` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `approval_request_id` varchar(100) NOT NULL,
  `authorization_request_id` varchar(100) NOT NULL,
  `mission_id` varchar(100) NOT NULL,
  `risk_level` enum('LOW','MODERATE','HIGH','CRITICAL') NOT NULL,
  `reason` text NOT NULL,
  `required_approver_role` varchar(100) NOT NULL DEFAULT 'SECURITY_APPROVER',
  `status` enum('PENDING','APPROVED','DENIED','EXPIRED','CANCELLED') NOT NULL DEFAULT 'PENDING',
  `expires_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gov_approval_request_id` (`approval_request_id`),
  KEY `idx_gov_approval_mission` (`mission_id`,`status`,`expires_at`),
  KEY `idx_gov_approval_authorization` (`authorization_request_id`),
  CONSTRAINT `fk_gov_approval_authorization` FOREIGN KEY (`authorization_request_id`) REFERENCES `gov_authorization_requests` (`request_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `gov_approval_requests` */

/*Table structure for table `gov_audit_log` */

DROP TABLE IF EXISTS `gov_audit_log`;

CREATE TABLE `gov_audit_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `audit_id` varchar(100) NOT NULL,
  `event_type` varchar(100) NOT NULL,
  `actor_id` varchar(255) DEFAULT NULL,
  `mission_id` varchar(100) DEFAULT NULL,
  `subject_type` varchar(100) DEFAULT NULL,
  `subject_id` varchar(255) DEFAULT NULL,
  `payload_json` longtext DEFAULT NULL,
  `previous_hash` char(64) DEFAULT NULL,
  `record_hash` char(64) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gov_audit_id` (`audit_id`),
  KEY `idx_gov_audit_mission` (`mission_id`,`created_at`),
  KEY `idx_gov_audit_subject` (`subject_type`,`subject_id`,`created_at`),
  KEY `idx_gov_audit_event` (`event_type`,`created_at`),
  CONSTRAINT `chk_gov_audit_payload_json` CHECK (`payload_json` is null or json_valid(`payload_json`))
) ENGINE=InnoDB AUTO_INCREMENT=2763 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

