/*Table structure for table `gov_authorization_requests` */

DROP TABLE IF EXISTS `gov_authorization_requests`;

CREATE TABLE `gov_authorization_requests` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `request_id` varchar(100) NOT NULL,
  `mission_id` varchar(100) NOT NULL,
  `scope_contract_id` varchar(100) DEFAULT NULL,
  `subject_component` varchar(255) NOT NULL,
  `action_class` varchar(100) NOT NULL,
  `action_name` varchar(255) NOT NULL,
  `resource_type` varchar(100) NOT NULL,
  `resource_value` varchar(1000) NOT NULL,
  `context_json` longtext DEFAULT NULL,
  `evidence_refs_json` longtext DEFAULT NULL,
  `requested_by` varchar(255) DEFAULT NULL,
  `request_status` enum('EVALUATING','ALLOW','DENY','REVIEW','CANCELLED') NOT NULL DEFAULT 'EVALUATING',
  `requested_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gov_authorization_request_id` (`request_id`),
  KEY `idx_gov_authorization_mission` (`mission_id`,`request_status`,`requested_at`),
  KEY `idx_gov_authorization_scope` (`scope_contract_id`),
  CONSTRAINT `fk_gov_authorization_scope` FOREIGN KEY (`scope_contract_id`) REFERENCES `gov_scope_contracts` (`scope_contract_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `chk_gov_authorization_context_json` CHECK (`context_json` is null or json_valid(`context_json`)),
  CONSTRAINT `chk_gov_authorization_evidence_json` CHECK (`evidence_refs_json` is null or json_valid(`evidence_refs_json`))
) ENGINE=InnoDB AUTO_INCREMENT=2313 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

