/*Table structure for table `gov_compliance_obligations` */

DROP TABLE IF EXISTS `gov_compliance_obligations`;

CREATE TABLE `gov_compliance_obligations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `obligation_id` varchar(100) NOT NULL,
  `policy_set_id` varchar(100) NOT NULL,
  `action_class` varchar(100) DEFAULT NULL,
  `obligation_type` varchar(100) NOT NULL,
  `description` text NOT NULL,
  `mandatory` tinyint(1) NOT NULL DEFAULT 1,
  `config_json` longtext DEFAULT NULL,
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gov_compliance_obligation_id` (`obligation_id`),
  KEY `idx_gov_compliance_policy` (`policy_set_id`,`enabled`,`action_class`),
  CONSTRAINT `fk_gov_compliance_policy` FOREIGN KEY (`policy_set_id`) REFERENCES `gov_policy_sets` (`policy_set_id`) ON UPDATE CASCADE,
  CONSTRAINT `chk_gov_compliance_config_json` CHECK (`config_json` is null or json_valid(`config_json`))
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

