/*Table structure for table `gov_policy_decisions` */

DROP TABLE IF EXISTS `gov_policy_decisions`;

CREATE TABLE `gov_policy_decisions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `decision_id` varchar(100) NOT NULL,
  `request_id` varchar(100) NOT NULL,
  `mission_id` varchar(100) NOT NULL,
  `policy_set_id` varchar(100) DEFAULT NULL,
  `policy_version` int(11) DEFAULT NULL,
  `scope_contract_id` varchar(100) DEFAULT NULL,
  `scope_version` int(11) DEFAULT NULL,
  `decision` enum('ALLOW','DENY','REVIEW') NOT NULL,
  `reason_codes_json` longtext NOT NULL,
  `constraints_json` longtext DEFAULT NULL,
  `requires_human_approval` tinyint(1) NOT NULL DEFAULT 0,
  `approval_request_id` varchar(100) DEFAULT NULL,
  `valid_from` datetime NOT NULL,
  `valid_until` datetime NOT NULL,
  `decision_hash` char(64) NOT NULL,
  `supersedes_decision_id` varchar(100) DEFAULT NULL,
  `decision_status` enum('ACTIVE','REVOKED','EXPIRED','SUPERSEDED') NOT NULL DEFAULT 'ACTIVE',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gov_policy_decision_id` (`decision_id`),
  KEY `idx_gov_policy_decision_request` (`request_id`,`created_at`),
  KEY `idx_gov_policy_decision_mission` (`mission_id`,`decision_status`,`valid_until`),
  KEY `idx_gov_policy_decision_scope` (`scope_contract_id`,`decision_status`),
  KEY `fk_gov_policy_decision_approval` (`approval_request_id`),
  CONSTRAINT `fk_gov_policy_decision_approval` FOREIGN KEY (`approval_request_id`) REFERENCES `gov_approval_requests` (`approval_request_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_gov_policy_decision_request` FOREIGN KEY (`request_id`) REFERENCES `gov_authorization_requests` (`request_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_gov_policy_decision_scope` FOREIGN KEY (`scope_contract_id`) REFERENCES `gov_scope_contracts` (`scope_contract_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `chk_gov_policy_decision_reasons_json` CHECK (json_valid(`reason_codes_json`)),
  CONSTRAINT `chk_gov_policy_decision_constraints_json` CHECK (`constraints_json` is null or json_valid(`constraints_json`))
) ENGINE=InnoDB AUTO_INCREMENT=2316 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

