/*Table structure for table `gov_policy_rules` */

DROP TABLE IF EXISTS `gov_policy_rules`;

CREATE TABLE `gov_policy_rules` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `rule_id` varchar(100) NOT NULL,
  `policy_set_id` varchar(100) NOT NULL,
  `priority` int(11) NOT NULL DEFAULT 100,
  `rule_name` varchar(255) NOT NULL,
  `rule_type` varchar(100) NOT NULL,
  `effect` enum('ALLOW','DENY','REVIEW') NOT NULL,
  `action_class` varchar(100) DEFAULT NULL,
  `condition_json` longtext DEFAULT NULL,
  `obligations_json` longtext DEFAULT NULL,
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gov_policy_rule_id` (`rule_id`),
  KEY `idx_gov_policy_rules_set_priority` (`policy_set_id`,`enabled`,`priority`),
  CONSTRAINT `fk_gov_policy_rules_set` FOREIGN KEY (`policy_set_id`) REFERENCES `gov_policy_sets` (`policy_set_id`) ON UPDATE CASCADE,
  CONSTRAINT `chk_gov_policy_rules_condition_json` CHECK (`condition_json` is null or json_valid(`condition_json`)),
  CONSTRAINT `chk_gov_policy_rules_obligations_json` CHECK (`obligations_json` is null or json_valid(`obligations_json`))
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `gov_policy_rules` */

insert  into `gov_policy_rules`(`id`,`rule_id`,`policy_set_id`,`priority`,`rule_name`,`rule_type`,`effect`,`action_class`,`condition_json`,`obligations_json`,`enabled`,`created_at`,`updated_at`) values 
(1,'GOV-R001','default-policy',1,'Emergency stop preempts target actions','HARD_GUARD','DENY',NULL,'{\"when\":\"emergency_stop_active\",\"except\":[\"INTERNAL_REASONING\",\"REPORTING\"]}','{\"reason_code\":\"EMERGENCY_STOP_ACTIVE\"}',1,'2026-08-13 07:01:07','2026-08-13 07:01:07'),
(2,'GOV-R010','default-policy',10,'Destructive actions are forbidden','HARD_GUARD','DENY','DESTRUCTIVE_ACTION','{\"always\":true}','{\"reason_code\":\"HARD_DENY_DESTRUCTIVE_ACTION\"}',1,'2026-08-13 07:01:07','2026-08-13 07:01:07'),
(3,'GOV-R020','default-policy',20,'Unknown actions are deny-by-default','DEFAULT','DENY',NULL,'{\"unknown_action\":true}','{\"reason_code\":\"UNKNOWN_ACTION_DENIED\"}',1,'2026-08-13 07:01:07','2026-08-13 07:01:07'),
(4,'GOV-R100','default-policy',100,'Internal reasoning has no target actuation authority','BOUNDARY','ALLOW','INTERNAL_REASONING','{\"target_actuation\":false}','{\"constraints\":{\"target_actuation\":false}}',1,'2026-08-13 07:01:07','2026-08-13 07:01:07'),
(5,'GOV-R110','default-policy',110,'Reporting has no target actuation authority','BOUNDARY','ALLOW','REPORTING','{\"target_actuation\":false}','{\"constraints\":{\"target_actuation\":false}}',1,'2026-08-13 07:01:07','2026-08-13 07:01:07'),
(6,'GOV-R200','default-policy',200,'CTI source reads require source allowlist','SCOPE_GUARD','ALLOW','CTI_SOURCE_READ','{\"requires_source_allowlist\":true}','{\"reason_code\":\"SOURCE_ALLOWLIST_REQUIRED\"}',1,'2026-08-13 07:01:07','2026-08-13 07:01:07');

/*Table structure for table `gov_policy_sets` */

DROP TABLE IF EXISTS `gov_policy_sets`;

CREATE TABLE `gov_policy_sets` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `policy_set_id` varchar(100) NOT NULL,
  `name` varchar(255) NOT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  `status` enum('DRAFT','ACTIVE','RETIRED') NOT NULL DEFAULT 'DRAFT',
  `default_effect` enum('DENY','REVIEW') NOT NULL DEFAULT 'DENY',
  `effective_from` datetime DEFAULT NULL,
  `effective_until` datetime DEFAULT NULL,
  `description` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gov_policy_sets_id` (`policy_set_id`),
  KEY `idx_gov_policy_sets_status` (`status`,`version`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `gov_policy_sets` */

insert  into `gov_policy_sets`(`id`,`policy_set_id`,`name`,`version`,`status`,`default_effect`,`effective_from`,`effective_until`,`description`,`created_at`,`updated_at`) values 
(1,'default-policy','APTS Default Governance Policy',1,'ACTIVE','DENY','2026-08-13 07:01:07',NULL,'Deny-by-default baseline policy for CTI and future Pentest subsystems.','2026-08-13 07:01:07','2026-08-13 07:01:07');

/*Table structure for table `gov_risk_assessments` */

DROP TABLE IF EXISTS `gov_risk_assessments`;

CREATE TABLE `gov_risk_assessments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `assessment_id` varchar(100) NOT NULL,
  `request_id` varchar(100) NOT NULL,
  `mission_id` varchar(100) NOT NULL,
  `risk_score` decimal(6,2) NOT NULL,
  `risk_level` enum('LOW','MODERATE','HIGH','CRITICAL') NOT NULL,
  `factors_json` longtext NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gov_risk_assessment_id` (`assessment_id`),
