/*Table structure for table `gov_scope_action_constraints` */

DROP TABLE IF EXISTS `gov_scope_action_constraints`;

CREATE TABLE `gov_scope_action_constraints` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `constraint_id` varchar(100) NOT NULL,
  `scope_contract_id` varchar(100) NOT NULL,
  `action_class` varchar(100) NOT NULL,
  `action_name` varchar(255) NOT NULL DEFAULT '*',
  `effect` enum('ALLOW','DENY','REVIEW') NOT NULL DEFAULT 'DENY',
  `max_risk_level` enum('LOW','MODERATE','HIGH','CRITICAL') NOT NULL DEFAULT 'LOW',
  `requires_approval` tinyint(1) NOT NULL DEFAULT 0,
  `constraints_json` longtext DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gov_action_constraint_id` (`constraint_id`),
  KEY `idx_gov_action_constraint_lookup` (`scope_contract_id`,`action_class`,`action_name`,`effect`),
  CONSTRAINT `fk_gov_action_constraint_contract` FOREIGN KEY (`scope_contract_id`) REFERENCES `gov_scope_contracts` (`scope_contract_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_gov_action_constraint_json` CHECK (`constraints_json` is null or json_valid(`constraints_json`))
) ENGINE=InnoDB AUTO_INCREMENT=297 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

