/*Table structure for table `gov_scope_contracts` */

DROP TABLE IF EXISTS `gov_scope_contracts`;

CREATE TABLE `gov_scope_contracts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `scope_contract_id` varchar(100) NOT NULL,
  `mission_id` varchar(100) NOT NULL,
  `name` varchar(255) NOT NULL,
  `status` enum('DRAFT','ACTIVE','SUSPENDED','EXPIRED','REVOKED') NOT NULL DEFAULT 'DRAFT',
  `policy_set_id` varchar(100) NOT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  `valid_from` datetime DEFAULT NULL,
  `valid_until` datetime DEFAULT NULL,
  `created_by` varchar(255) NOT NULL,
  `approved_by` varchar(255) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `metadata_json` longtext DEFAULT NULL,
  `contract_hash` char(64) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gov_scope_contract_id` (`scope_contract_id`),
  KEY `idx_gov_scope_contract_mission` (`mission_id`,`status`,`version`),
  KEY `idx_gov_scope_contract_validity` (`status`,`valid_from`,`valid_until`),
  KEY `fk_gov_scope_contract_policy` (`policy_set_id`),
  CONSTRAINT `fk_gov_scope_contract_policy` FOREIGN KEY (`policy_set_id`) REFERENCES `gov_policy_sets` (`policy_set_id`) ON UPDATE CASCADE,
  CONSTRAINT `chk_gov_scope_metadata_json` CHECK (`metadata_json` is null or json_valid(`metadata_json`))
