/*Table structure for table `gov_scope_sources` */

DROP TABLE IF EXISTS `gov_scope_sources`;

CREATE TABLE `gov_scope_sources` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `scope_source_id` varchar(100) NOT NULL,
  `scope_contract_id` varchar(100) NOT NULL,
  `source_id` varchar(255) NOT NULL,
  `source_type` varchar(100) NOT NULL DEFAULT 'CTI',
  `allowed` tinyint(1) NOT NULL DEFAULT 1,
  `constraints_json` longtext DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gov_scope_source_id` (`scope_source_id`),
  KEY `idx_gov_scope_source_contract` (`scope_contract_id`,`allowed`),
  KEY `idx_gov_scope_source_source` (`source_id`),
  CONSTRAINT `fk_gov_scope_source_contract` FOREIGN KEY (`scope_contract_id`) REFERENCES `gov_scope_contracts` (`scope_contract_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_gov_scope_source_constraints_json` CHECK (`constraints_json` is null or json_valid(`constraints_json`))
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `gov_scope_sources` */

/*Table structure for table `gov_scope_targets` */

DROP TABLE IF EXISTS `gov_scope_targets`;

CREATE TABLE `gov_scope_targets` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `scope_target_id` varchar(100) NOT NULL,
  `scope_contract_id` varchar(100) NOT NULL,
  `target_type` varchar(50) NOT NULL,
  `target_value` varchar(1000) NOT NULL,
  `normalized_value` varchar(1000) DEFAULT NULL,
  `environment` varchar(50) NOT NULL DEFAULT 'LAB',
  `allowed` tinyint(1) NOT NULL DEFAULT 1,
  `notes` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_gov_scope_target_id` (`scope_target_id`),
  KEY `idx_gov_scope_target_contract` (`scope_contract_id`,`allowed`),
  KEY `idx_gov_scope_target_value` (`normalized_value`(191)),
  CONSTRAINT `fk_gov_scope_target_contract` FOREIGN KEY (`scope_contract_id`) REFERENCES `gov_scope_contracts` (`scope_contract_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=113 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

